package vn.edu.fpt.beefcare.service;

import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.edu.fpt.beefcare.domain.*;
import vn.edu.fpt.beefcare.domain.enumeration.*;
import vn.edu.fpt.beefcare.service.dto.FarmDashboardDtos.ReportRequest;
import vn.edu.fpt.beefcare.service.dto.FarmDashboardDtos.ReportView;

/** Read-only implementation of the seven FE-15 reports, calculated from tenant-scoped source tables. */
@Service
public class FarmReportService {
    private final EntityManager em;private final FarmAccessService access;private final FarmClock clock;private final FarmDashboardService dashboard;
    public FarmReportService(EntityManager em,FarmAccessService access,FarmClock clock,FarmDashboardService dashboard){this.em=em;this.access=access;this.clock=clock;this.dashboard=dashboard;}

    @Transactional(readOnly=true)
    public ReportView report(Long farmId,ReportRequest request){
        FarmContext ctx=access.require(farmId,FarmAction.VIEW_REPORTS);validate(request);
        List<Map<String,Object>> rows=new ArrayList<>();Map<String,Object> summary=new LinkedHashMap<>();List<String> unavailable=new ArrayList<>();
        switch(request.reportType()){
            case "RPT-01" -> herd(farmId,request,rows,summary);
            case "RPT-02" -> growth(farmId,request,rows,summary);
            case "RPT-03" -> vaccination(farmId,request,rows,summary);
            case "RPT-04" -> health(farmId,request,rows,summary);
            case "RPT-05" -> reproduction(farmId,request,rows,summary,unavailable);
            case "RPT-06" -> movements(farmId,request,rows,summary);
            case "RPT-07" -> fattening(farmId,request,rows,summary,unavailable);
            default -> throw DomainException.invalid("reportType");
        }
        return new ReportView(request.reportType(),request.from(),request.to(),clock.now(),Collections.unmodifiableMap(new LinkedHashMap<>(summary)),List.copyOf(rows),List.copyOf(unavailable));
    }

    private void herd(Long farm,ReportRequest r,List<Map<String,Object>> rows,Map<String,Object> summary){
        LocalDate end=r.to();List<Cattle> animals=em.createQuery("select c from Cattle c where c.farm.id=:farm and c.herdStatus<>:voided",Cattle.class).setParameter("farm",farm).setParameter("voided",HerdStatus.VOIDED).getResultList();
        Map<String,Long> groups=new TreeMap<>(),pens=new TreeMap<>(),breeds=new TreeMap<>(),purposes=new TreeMap<>(),stages=new TreeMap<>();long head=0;
        for(Cattle c:animals){LocalDate entry=em.createQuery("select min(e.entryDate) from HerdEntry e where e.cattle.id=:id and e.status=:valid",LocalDate.class).setParameter("id",c.getId()).setParameter("valid",EntryLineStatus.VALID).getSingleResult();LocalDate exit=c.getExitDate();if(entry==null||entry.isAfter(end)||exit!=null&&!exit.isAfter(end))continue;if(!matches(c,r))continue;head++;String group=group(c);groups.merge(group,1L,Long::sum);breeds.merge(c.getBreed().getName(),1L,Long::sum);purposes.merge(c.getPurpose().getName(),1L,Long::sum);stages.merge(c.getLifeStage().name(),1L,Long::sum);String pen=penAt(c.getId(),end);if(pen!=null)pens.merge(pen,1L,Long::sum);}
        rows.addAll(dimensions("herdGroup",groups));rows.addAll(dimensions("pen",pens));rows.addAll(dimensions("breed",breeds));rows.addAll(dimensions("purpose",purposes));rows.addAll(dimensions("lifeStage",stages));
        long entries=count("select count(e) from HerdEntry e where e.farm.id=:farm and e.status=:valid and e.entryDate between :from and :to",farm,r.from(),end);
        long exits=count("select count(e) from HerdExit e where e.farm.id=:farm and e.status=:valid and e.voucher.status=:confirmed and e.voucher.exitDate between :from and :to",farm,r.from(),end);
        summary.put("headAtEnd",head);summary.put("entriesInPeriod",entries);summary.put("exitsInPeriod",exits);summary.put("entriesBySource",groupCount("select e.source, count(e) from HerdEntry e where e.farm.id=:farm and e.status=:valid and e.entryDate between :from and :to group by e.source",farm,r.from(),end));summary.put("exitsByType",groupCount("select e.voucher.exitType, count(e) from HerdExit e where e.farm.id=:farm and e.status=:valid and e.voucher.status=:confirmed and e.voucher.exitDate between :from and :to group by e.voucher.exitType",farm,r.from(),end));
    }

    private void growth(Long farm,ReportRequest r,List<Map<String,Object>> rows,Map<String,Object> summary){
        List<Growth> events=em.createQuery("select g from Growth g where g.cattle.farm.id=:farm and g.status in ('VALID','CORRECTED') and g.checkDate between :from and :to order by g.cattle.id,g.checkDate,g.id",Growth.class).setParameter("farm",farm).setParameter("from",r.from()).setParameter("to",r.to()).getResultList();
        Map<String,List<Growth>> groups=new TreeMap<>();for(Growth g:events){if(!matches(g.getCattle(),r))continue;String key=group(g.getCattle())+"|"+penAt(g.getCattle().getId(),g.getCheckDate())+"|"+g.getCattle().getLifeStage().name();groups.computeIfAbsent(key,k->new ArrayList<>()).add(g);}
        int estimated=0;BigDecimal totalWeight=BigDecimal.ZERO;int weightCount=0;List<BigDecimal> adgs=new ArrayList<>();
        for(var e:groups.entrySet()){List<Growth> list=e.getValue();long n=list.stream().filter(g->g.getWeightKg()!=null).count();BigDecimal avg=list.stream().map(Growth::getWeightKg).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);if(n>0){avg=avg.divide(BigDecimal.valueOf(n),2,RoundingMode.HALF_UP);totalWeight=totalWeight.add(avg);weightCount++;}long est=list.stream().filter(g->g.getWeightKg()!=null&&"ESTIMATED".equalsIgnoreCase(g.getWeightType())).count();estimated+=est;BigDecimal adg=null;Map<Long,List<Growth>> byCattle=new HashMap<>();list.stream().filter(g->g.getWeightKg()!=null).forEach(g->byCattle.computeIfAbsent(g.getCattle().getId(),k->new ArrayList<>()).add(g));for(List<Growth> w:byCattle.values())if(w.size()>=2){long days=ChronoUnit.DAYS.between(w.get(0).getCheckDate(),w.get(w.size()-1).getCheckDate());if(days>=14)adgs.add(w.get(w.size()-1).getWeightKg().subtract(w.get(0).getWeightKg()).divide(BigDecimal.valueOf(days),3,RoundingMode.HALF_UP));}rows.add(row("group",e.getKey(),"validWeighings",list.size(),"averageWeightKg",n==0?null:avg,"estimatedShare",n==0?null:BigDecimal.valueOf(est).divide(BigDecimal.valueOf(n),4,RoundingMode.HALF_UP)));}
        summary.put("validWeighings",events.size());summary.put("averageGroupWeightKg",weightCount==0?null:totalWeight.divide(BigDecimal.valueOf(weightCount),2,RoundingMode.HALF_UP));summary.put("estimatedWeightCount",estimated);summary.put("averageADGKgPerDay",average(adgs));
    }

    private void vaccination(Long farm,ReportRequest r,List<Map<String,Object>> rows,Map<String,Object> summary){
        List<ScheduledDose> doses=em.createQuery("select d from ScheduledDose d where d.cattle.farm.id=:farm and d.dueDate between :from and :to",ScheduledDose.class).setParameter("farm",farm).setParameter("from",r.from()).setParameter("to",r.to()).getResultList();
        Map<String,long[]> bySchedule=new TreeMap<>();for(ScheduledDose d:doses){if(!matches(d.getCattle(),r))continue;String name=d.getSchedule().getScheduleName();long[] counts=bySchedule.computeIfAbsent(name,k->new long[4]);String state=d.getVaccination()!=null&&"VALID".equalsIgnoreCase(d.getVaccination().getStatus())?"DONE":d.getStatus();if("DONE".equalsIgnoreCase(state))counts[1]++;else if("DEFERRED".equalsIgnoreCase(state))counts[2]++;else if("CANCELLED".equalsIgnoreCase(state)){}else if(d.getDueDate().isBefore(r.to()))counts[3]++;else counts[0]++;}
        bySchedule.forEach((name,c)->rows.add(row("schedule",name,"planned",c[0],"done",c[1],"deferred",c[2],"overdue",c[3])));
        List<Vaccination> shots=em.createQuery("select v from Vaccination v where v.cattle.farm.id=:farm and v.vaccinationDate between :from and :to and upper(v.source)='ON_FARM' and upper(v.status) in ('VALID','CORRECTED')",Vaccination.class).setParameter("farm",farm).setParameter("from",r.from()).setParameter("to",r.to()).getResultList();Map<String,Long> byVaccine=new TreeMap<>();for(Vaccination v:shots)if(matches(v.getCattle(),r))byVaccine.merge(v.getVaccine().getName(),1L,Long::sum);rows.addAll(dimensions("onFarmVaccine",byVaccine));summary.put("doses",doses.size());summary.put("onFarmVaccinations",shots.size());
    }

    private void health(Long farm,ReportRequest r,List<Map<String,Object>> rows,Map<String,Object> summary){
        List<HealthCase> cases=em.createQuery("select h from HealthCase h where h.cattle.farm.id=:farm and h.openedDate between :from and :to",HealthCase.class).setParameter("farm",farm).setParameter("from",r.from()).setParameter("to",r.to()).getResultList();Map<String,Long> byOutcome=new TreeMap<>(),bySeverity=new TreeMap<>();for(HealthCase h:cases)if(matches(h.getCattle(),r)){byOutcome.merge(Objects.toString(h.getOutcome(),"OPEN"),1L,Long::sum);bySeverity.merge(Objects.toString(h.getSeverity(),"UNSPECIFIED"),1L,Long::sum);}rows.addAll(dimensions("caseOutcome",byOutcome));rows.addAll(dimensions("severity",bySeverity));
        String timezone=access.require(farm,FarmAction.VIEW_REPORTS).farm().getTimeZone();ZoneId zone=timezone==null?ZoneId.of("Asia/Ho_Chi_Minh"):ZoneId.of(timezone);
        List<Treatment> treatments=em.createQuery("select t from Treatment t where t.healthCase.cattle.farm.id=:farm and t.treatmentTime>=:from and t.treatmentTime<:until and upper(t.status) in ('VALID','CORRECTED')",Treatment.class).setParameter("farm",farm).setParameter("from",r.from().atStartOfDay(zone).toInstant()).setParameter("until",r.to().plusDays(1).atStartOfDay(zone).toInstant()).getResultList();Map<String,Long> byMedicine=new TreeMap<>();for(Treatment t:treatments)if(matches(t.getHealthCase().getCattle(),r))byMedicine.merge(t.getMedicineNameSnapshot()==null?(t.getMedicine()==null?"Unspecified":t.getMedicine().getName()):t.getMedicineNameSnapshot(),1L,Long::sum);rows.addAll(dimensions("treatmentMedicine",byMedicine));
        long chronic=em.createQuery("select count(h) from HealthCase h where h.cattle.farm.id=:farm and upper(h.status)='CHRONIC' and h.openedDate<=:end",Long.class).setParameter("farm",farm).setParameter("end",r.to()).getSingleResult();List<Long> withTreatment=em.createQuery("select distinct t.healthCase.cattle.id from Treatment t where t.healthCase.cattle.farm.id=:farm and upper(t.status) in ('VALID','CORRECTED') and t.withdrawalEndDate>=:end",Long.class).setParameter("farm",farm).setParameter("end",r.to()).getResultList();List<Long> withVaccination=em.createQuery("select distinct v.cattle.id from Vaccination v where v.cattle.farm.id=:farm and upper(v.status) in ('VALID','CORRECTED') and v.withdrawalEndDate>=:end",Long.class).setParameter("farm",farm).setParameter("end",r.to()).getResultList();Set<Long> activeWithdrawal=new HashSet<>(withTreatment);activeWithdrawal.addAll(withVaccination);long chronicSince=em.createQuery("select count(h) from HealthCase h where h.cattle.farm.id=:farm and upper(h.status)='CHRONIC' and h.chronicSince between :from and :to",Long.class).setParameter("farm",farm).setParameter("from",r.from()).setParameter("to",r.to()).getSingleResult();long closed=em.createQuery("select count(h) from HealthCase h where h.cattle.farm.id=:farm and h.closedDate between :from and :to",Long.class).setParameter("farm",farm).setParameter("from",r.from()).setParameter("to",r.to()).getSingleResult();summary.put("openedCases",cases.size());summary.put("movedToChronic",chronicSince);summary.put("closedCases",closed);summary.put("casesByOutcome",byOutcome);summary.put("casesBySeverity",bySeverity);summary.put("chronicAtEnd",chronic);summary.put("treatments",treatments.size());summary.put("treatmentsByMedicine",byMedicine);summary.put("cattleWithActiveMeatWithdrawalAtEnd",activeWithdrawal.size());
    }

    private void reproduction(Long farm,ReportRequest r,List<Map<String,Object>> rows,Map<String,Object> summary,List<String> unavailable){
        Instant from=start(r.from(),farm),until=start(r.to().plusDays(1),farm);ZoneId zone=farmZone(farm);
        List<ReproductionEvent> events=em.createQuery("select e from ReproductionEvent e where e.cattle.farm.id=:farm and e.eventTime>=:from and e.eventTime<:until and upper(e.status) in ('VALID','CORRECTED') order by e.eventTime",ReproductionEvent.class).setParameter("farm",farm).setParameter("from",from).setParameter("until",until).getResultList();Map<String,Long> counts=new TreeMap<>();Set<Long> females=new HashSet<>();for(ReproductionEvent e:events){if(!matches(e.getCattle(),r))continue;counts.merge(e.getType()+":"+Objects.toString(e.getResult(),""),1L,Long::sum);if(e.getCattle().getSex()==Sex.FEMALE)females.add(e.getCattle().getId());}rows.addAll(dimensions("eventTypeAndResult",counts));
        List<CalvingEvent> calvings=em.createQuery("select c from CalvingEvent c where c.dam.farm.id=:farm and c.birthTime>=:from and c.birthTime<:until and upper(c.status) in ('VALID','CORRECTED') order by c.dam.id,c.birthTime",CalvingEvent.class).setParameter("farm",farm).setParameter("from",from).setParameter("until",until).getResultList().stream().filter(c->matches(c.getDam(),r)).toList();for(CalvingEvent c:calvings)females.add(c.getDam().getId());
        List<CalvingEvent> allCalvings=em.createQuery("select c from CalvingEvent c where c.dam.farm.id=:farm and c.birthTime<:until and upper(c.status) in ('VALID','CORRECTED') order by c.dam.id,c.birthTime",CalvingEvent.class).setParameter("farm",farm).setParameter("until",until).getResultList().stream().filter(c->matches(c.getDam(),r)).toList();
        List<ReproductionEvent> allBreedings=em.createQuery("select e from ReproductionEvent e where e.cattle.farm.id=:farm and upper(e.type)='BREEDING' and e.eventTime<:until and upper(e.status) in ('VALID','CORRECTED') order by e.cattle.id,e.eventTime",ReproductionEvent.class).setParameter("farm",farm).setParameter("until",until).getResultList().stream().filter(e->matches(e.getCattle(),r)).toList();
        List<ReproductionEvent> checks=em.createQuery("select e from ReproductionEvent e where e.cattle.farm.id=:farm and upper(e.type)='PREGNANCY_CHECK' and e.eventTime<:until and upper(e.status) in ('VALID','CORRECTED') order by e.eventTime",ReproductionEvent.class).setParameter("farm",farm).setParameter("until",until).getResultList().stream().filter(e->matches(e.getCattle(),r)).toList();
        Map<Long,String> checkResultByBreeding=new HashMap<>();for(ReproductionEvent check:checks)if(check.getLinkedEvent()!=null&&check.getResult()!=null)checkResultByBreeding.put(check.getLinkedEvent().getId(),check.getResult().toUpperCase(Locale.ROOT));
        List<BigDecimal> intervalDays=new ArrayList<>(),daysOpen=new ArrayList<>(),servicesPerConception=new ArrayList<>(),ageFirstCalving=new ArrayList<>();
        Map<Long,List<CalvingEvent>> calvesByDam=new HashMap<>();allCalvings.forEach(c->calvesByDam.computeIfAbsent(c.getDam().getId(),k->new ArrayList<>()).add(c));
        for(List<CalvingEvent> damCalvings:calvesByDam.values())for(int i=1;i<damCalvings.size();i++){CalvingEvent current=damCalvings.get(i),previous=damCalvings.get(i-1);if(!current.getBirthTime().isBefore(from)){long days=ChronoUnit.DAYS.between(previous.getBirthTime(),current.getBirthTime());if(days>=0)intervalDays.add(BigDecimal.valueOf(days));}}
        List<PregnancyEpisode> closedEpisodes=em.createQuery("select p from PregnancyEpisode p where p.cattle.farm.id=:farm and p.closedDate between :fromDate and :toDate",PregnancyEpisode.class).setParameter("farm",farm).setParameter("fromDate",r.from()).setParameter("toDate",r.to()).getResultList().stream().filter(p->matches(p.getCattle(),r)).toList();
        for(PregnancyEpisode episode:closedEpisodes){ReproductionEvent conceiving=episode.getLinkedBreeding();if(conceiving==null||!"CALVED".equalsIgnoreCase(episode.getStatus())||conceiving.getEventTime().isBefore(from))continue;List<CalvingEvent> damCalvings=calvesByDam.getOrDefault(episode.getCattle().getId(),List.of());Instant previousCalving=damCalvings.stream().map(CalvingEvent::getBirthTime).filter(t->t.isBefore(conceiving.getEventTime())).max(Instant::compareTo).orElse(null);if(previousCalving!=null)daysOpen.add(BigDecimal.valueOf(ChronoUnit.DAYS.between(previousCalving,conceiving.getEventTime())));long services=allBreedings.stream().filter(b->b.getCattle().getId().equals(episode.getCattle().getId())&&b.getEventTime().isBefore(conceiving.getEventTime())&&!b.getEventTime().isBefore(previousCalving==null?Instant.MIN:previousCalving)).count()+1;if(services>0)servicesPerConception.add(BigDecimal.valueOf(services));}
        for(Cattle cow:em.createQuery("select c from Cattle c where c.farm.id=:farm and c.sex=:female",Cattle.class).setParameter("farm",farm).setParameter("female",Sex.FEMALE).getResultList()){if(!matches(cow,r))continue;List<CalvingEvent> damCalvings=calvesByDam.getOrDefault(cow.getId(),List.of());if(!damCalvings.isEmpty()&&cow.getBirthDate()!=null){CalvingEvent first=damCalvings.get(0);if(!first.getBirthTime().isBefore(from)&&!first.getBirthTime().isAfter(until))ageFirstCalving.add(BigDecimal.valueOf(ChronoUnit.DAYS.between(cow.getBirthDate(),first.getBirthTime().atZone(zone).toLocalDate())/30.4375));}}
        List<ReproductionEvent> periodBreedings=allBreedings.stream().filter(e->!e.getEventTime().isBefore(from)).toList();long decided=0,conceptions=0,firstDecided=0,firstConceptions=0;for(ReproductionEvent breeding:periodBreedings){String result=checkResultByBreeding.get(breeding.getId());if("PREGNANT".equals(result)||"NOT_PREGNANT".equals(result)){decided++;if("PREGNANT".equals(result))conceptions++;Instant previousCalving=calvesByDam.getOrDefault(breeding.getCattle().getId(),List.of()).stream().map(CalvingEvent::getBirthTime).filter(t->t.isBefore(breeding.getEventTime())).max(Instant::compareTo).orElse(Instant.MIN);boolean earlierService=allBreedings.stream().anyMatch(other->other.getCattle().getId().equals(breeding.getCattle().getId())&&other.getEventTime().isBefore(breeding.getEventTime())&&!other.getEventTime().isBefore(previousCalving));if(!earlierService){firstDecided++;if("PREGNANT".equals(result))firstConceptions++;}}}
        long episodeOutcomes=closedEpisodes.stream().filter(p->Set.of("CALVED","LOST").contains(p.getStatus().toUpperCase(Locale.ROOT))).count(),losses=closedEpisodes.stream().filter(p->"LOST".equalsIgnoreCase(p.getStatus())).count();long liveCalves=em.createQuery("select count(o) from CalfOutcome o where o.calving.dam.farm.id=:farm and o.calving.birthTime>=:from and o.calving.birthTime<:until and o.outcome='LIVE'",Long.class).setParameter("farm",farm).setParameter("from",from).setParameter("until",until).getSingleResult();long stillborn=em.createQuery("select count(o) from CalfOutcome o where o.calving.dam.farm.id=:farm and o.calving.birthTime>=:from and o.calving.birthTime<:until and o.outcome='STILLBORN'",Long.class).setParameter("farm",farm).setParameter("from",from).setParameter("until",until).getSingleResult();
        Map<String,Object> overdue=overdueFemales(farm,r,allCalvings,until,zone);summary.put("trackedFemales",females.size());summary.put("breedings",countType(events,"BREEDING"));summary.put("checks",countType(events,"PREGNANCY_CHECK"));summary.put("calvings",calvings.size());summary.put("liveCalves",liveCalves);summary.put("stillbirths",stillborn);summary.put("episodesLost",losses);summary.put("episodesCalved",closedEpisodes.stream().filter(p->"CALVED".equalsIgnoreCase(p.getStatus())).count());summary.put("averageCalvingIntervalDays",measuredAverage(intervalDays));summary.put("averageDaysOpen",measuredAverage(daysOpen));summary.put("averageServicesPerConception",measuredAverage(servicesPerConception));summary.put("overallConceptionRate",measuredRatio(conceptions,decided));summary.put("firstServiceConceptionRate",measuredRatio(firstConceptions,firstDecided));summary.put("pregnancyLossRate",measuredRatio(losses,episodeOutcomes));summary.put("averageAgeAtFirstCalvingMonths",measuredAverage(ageFirstCalving));summary.put("overdueFemales",overdue);
    }

    private Map<String,Object> overdueFemales(Long farm,ReportRequest request,List<CalvingEvent> allCalvings,Instant until,ZoneId zone){Map<Long,LocalDate> lastCalving=new HashMap<>();for(CalvingEvent c:allCalvings){LocalDate date=c.getBirthTime().atZone(zone).toLocalDate();lastCalving.merge(c.getDam().getId(),date,(a,b)->a.isAfter(b)?a:b);}LocalDate asOf=until.minusNanos(1).atZone(zone).toLocalDate();Map<String,Object> params=parameters(farm,asOf);int postpartum=Optional.ofNullable((Number)params.get("POST_CALVING_DAYS")).map(Number::intValue).orElse(63),cycle=Optional.ofNullable((Number)params.get("ESTRUS_CYCLE_DAYS")).map(Number::intValue).orElse(15);List<Cattle> females=em.createQuery("select c from Cattle c where c.farm.id=:farm and c.sex=:female and c.herdStatus=:active",Cattle.class).setParameter("farm",farm).setParameter("female",Sex.FEMALE).setParameter("active",HerdStatus.ACTIVE).getResultList();List<Map<String,Object>> overdue=new ArrayList<>();for(Cattle cow:females){if(!matches(cow,request)||cow.getPurpose()==null||cow.getPurpose().getPurposeType()!=PurposeType.BREEDING)continue;LocalDate last=lastCalving.get(cow.getId());if(last==null)continue;boolean pregnant=em.createQuery("select count(p) from PregnancyEpisode p where p.cattle.id=:id and upper(p.status)='OPEN'",Long.class).setParameter("id",cow.getId()).getSingleResult()>0;if(!pregnant&&ChronoUnit.DAYS.between(last,asOf)>postpartum+3L*cycle)overdue.add(row("cattleId",cow.getId(),"displayCode",cow.getDisplayCode(),"daysSinceCalving",ChronoUnit.DAYS.between(last,asOf)));}return Map.of("count",overdue.size(),"items",overdue);}
    private Map<String,Object> measuredAverage(List<BigDecimal> values){Map<String,Object> result=new LinkedHashMap<>();result.put("value",values.size()<3?null:average(values));result.put("n",values.size());result.put("status",values.size()<3?"INSUFFICIENT_DATA":"AVAILABLE");return result;}
    private Map<String,Object> measuredRatio(long numerator,long denominator){Map<String,Object> result=new LinkedHashMap<>();result.put("numerator",numerator);result.put("denominator",denominator);result.put("value",denominator<3?null:BigDecimal.valueOf(numerator).divide(BigDecimal.valueOf(denominator),4,RoundingMode.HALF_UP));result.put("n",denominator);result.put("status",denominator<3?"INSUFFICIENT_DATA":"AVAILABLE");return result;}

    private void movements(Long farm,ReportRequest r,List<Map<String,Object>> rows,Map<String,Object> summary){
        List<HerdEntry> entries=em.createQuery("select e from HerdEntry e where e.farm.id=:farm and e.status=:valid and e.entryDate between :from and :to",HerdEntry.class).setParameter("farm",farm).setParameter("valid",EntryLineStatus.VALID).setParameter("from",r.from()).setParameter("to",r.to()).getResultList().stream().filter(e->matches(e.getCattle(),r)).toList();List<HerdExit> exits=em.createQuery("select e from HerdExit e where e.farm.id=:farm and e.status=:valid and e.voucher.status=:confirmed and e.voucher.exitDate between :from and :to",HerdExit.class).setParameter("farm",farm).setParameter("valid",ExitLineStatus.CONFIRMED).setParameter("confirmed",ExitVoucherStatus.CONFIRMED).setParameter("from",r.from()).setParameter("to",r.to()).getResultList().stream().filter(e->matches(e.getCattle(),r)).toList();List<PenAssignment> moves=em.createQuery("select a from PenAssignment a where a.farm.id=:farm and a.fromDate between :from and :to and a.source=:source",PenAssignment.class).setParameter("farm",farm).setParameter("source",AssignmentSource.MOVE).setParameter("from",r.from()).setParameter("to",r.to()).getResultList().stream().filter(m->matches(m.getCattle(),r)).toList();rows.addAll(dimensions("entrySource",groupEnum(entries.stream().map(e->e.getSource().name()).toList())));rows.addAll(dimensions("exitType",groupEnum(exits.stream().map(e->e.getVoucher().getExitType().name()).toList())));rows.addAll(dimensions("penMoveTo",groupEnum(moves.stream().map(m->m.getPen().getCode()).toList())));summary.put("entries",entries.size());summary.put("exits",exits.size());summary.put("penMoves",moves.size());}

    private void fattening(Long farm,ReportRequest r,List<Map<String,Object>> rows,Map<String,Object> summary,List<String> unavailable){
        List<Cattle> cattle=em.createQuery("select c from Cattle c where c.farm.id=:farm and c.purpose.purposeType=:purpose and c.herdStatus<>:voided",Cattle.class).setParameter("farm",farm).setParameter("purpose",PurposeType.FATTENING).setParameter("voided",HerdStatus.VOIDED).getResultList();BigDecimal gainTotal=BigDecimal.ZERO,feedKg=BigDecimal.ZERO,startWeightTotal=BigDecimal.ZERO,endWeightTotal=BigDecimal.ZERO;long feedCost=0;List<BigDecimal> adgValues=new ArrayList<>(),projectedDays=new ArrayList<>();int included=0,insufficient=0,reached=0;Map<String,Map<String,Object>> byPen=new TreeMap<>();
        List<FeedingRecord> feeding=em.createQuery("select f from FeedingRecord f where f.farm.id=:farm and f.status='VALID' and f.feedingDate between :from and :to",FeedingRecord.class).setParameter("farm",farm).setParameter("from",r.from()).setParameter("to",r.to()).getResultList();Map<String,BigDecimal[]> penFeed=new HashMap<>();for(FeedingRecord f:feeding){List<FeedingRecordLine> lines=em.createQuery("select l from FeedingRecordLine l where l.feedingRecord.id=:id",FeedingRecordLine.class).setParameter("id",f.getId()).getResultList();BigDecimal[] totals=penFeed.computeIfAbsent(f.getPen().getCode(),k->new BigDecimal[]{BigDecimal.ZERO,BigDecimal.ZERO});for(FeedingRecordLine line:lines){totals[0]=totals[0].add(line.getActualKg());totals[1]=totals[1].add(BigDecimal.valueOf(line.getTotalCost()));}}
        int periodDays=(int)(ChronoUnit.DAYS.between(r.from(),r.to())+1);long totalHeadDays=0;BigDecimal targetValue=parameters(farm,r.to()).get("TARGET_FINISHING_WEIGHT_KG") instanceof Number n?new BigDecimal(n.toString()):null;
        for(Cattle c:cattle){if(!matches(c,r))continue;LocalDate entry=firstEntry(c.getId());LocalDate exit=c.getExitDate();LocalDate start=entry!=null&&entry.isAfter(r.from())?entry:r.from();LocalDate end=exit!=null&&!exit.isAfter(r.to())?exit:r.to();if(start.isAfter(end))continue;for(LocalDate day=start;!day.isAfter(end);day=day.plusDays(1))totalHeadDays++;BigDecimal startWeight=weightAt(c.getId(),start),endWeight=weightAt(c.getId(),end);if(startWeight==null||endWeight==null){insufficient++;continue;}BigDecimal gain=endWeight.subtract(startWeight);gainTotal=gainTotal.add(gain);startWeightTotal=startWeightTotal.add(startWeight);endWeightTotal=endWeightTotal.add(endWeight);included++;long days=Math.max(1,ChronoUnit.DAYS.between(start,end));BigDecimal animalAdg=gain.divide(BigDecimal.valueOf(days),3,RoundingMode.HALF_UP);adgValues.add(animalAdg);BigDecimal animalFeed=BigDecimal.ZERO;long animalCost=0;Map<LocalDate,Long> penByDay=new HashMap<>();for(PenAssignment a:em.createQuery("select a from PenAssignment a where a.cattle.id=:id and a.fromDate<=:to and (a.toDate is null or a.toDate>=:from)",PenAssignment.class).setParameter("id",c.getId()).setParameter("from",start).setParameter("to",end).getResultList()){LocalDate aFrom=a.getFromDate().isAfter(start)?a.getFromDate():start;LocalDate aTo=a.getToDate()==null||!a.getToDate().isBefore(end)?end:a.getToDate();for(LocalDate day=aFrom;!day.isAfter(aTo);day=day.plusDays(1))penByDay.put(day,a.getPen().getId());}
            for(FeedingRecord f:feeding)if(!f.getFeedingDate().isBefore(start)&&!f.getFeedingDate().isAfter(end)&&Objects.equals(penByDay.get(f.getFeedingDate()),f.getPen().getId())){long head=em.createQuery("select count(a) from PenAssignment a where a.pen.id=:pen and a.fromDate<=:day and (a.toDate is null or a.toDate>=:day)",Long.class).setParameter("pen",f.getPen().getId()).setParameter("day",f.getFeedingDate()).getSingleResult();if(head>0){List<FeedingRecordLine> ls=em.createQuery("select l from FeedingRecordLine l where l.feedingRecord.id=:id",FeedingRecordLine.class).setParameter("id",f.getId()).getResultList();for(FeedingRecordLine l:ls){animalFeed=animalFeed.add(l.getActualKg().divide(BigDecimal.valueOf(head),6,RoundingMode.HALF_UP));animalCost+=BigDecimal.valueOf(l.getTotalCost()).divide(BigDecimal.valueOf(head),0,RoundingMode.HALF_UP).longValue();}}}
            feedKg=feedKg.add(animalFeed);feedCost=Math.addExact(feedCost,animalCost);String pen=penAt(c.getId(),end);if(pen!=null){Map<String,Object> row=byPen.computeIfAbsent(pen,k->new LinkedHashMap<>());row.put("pen",pen);row.put("cattleCount",((Number)row.getOrDefault("cattleCount",0)).intValue()+1);row.put("gainKg",((BigDecimal)row.getOrDefault("gainKg",BigDecimal.ZERO)).add(gain));row.put("feedKg",((BigDecimal)row.getOrDefault("feedKg",BigDecimal.ZERO)).add(animalFeed));row.put("feedCost",((Long)row.getOrDefault("feedCost",0L))+animalCost);}if(targetValue!=null&&endWeight.compareTo(targetValue)>=0)reached++;if(targetValue!=null&&endWeight.compareTo(targetValue)<0){List<Growth> recent=em.createQuery("select g from Growth g where g.cattle.id=:id and g.status in ('VALID','CORRECTED') and g.weightKg is not null and g.checkDate between :from and :to order by g.checkDate,g.id",Growth.class).setParameter("id",c.getId()).setParameter("from",r.to().minusDays(60)).setParameter("to",r.to()).getResultList();if(recent.size()>=2){Growth first=recent.get(0),last=recent.get(recent.size()-1);long recentDays=ChronoUnit.DAYS.between(first.getCheckDate(),last.getCheckDate());if(recentDays>=14){BigDecimal recentAdg=last.getWeightKg().subtract(first.getWeightKg()).divide(BigDecimal.valueOf(recentDays),6,RoundingMode.HALF_UP);if(recentAdg.signum()>0)projectedDays.add(targetValue.subtract(endWeight).divide(recentAdg,0,RoundingMode.CEILING));}}}
        }
        for(Map<String,Object> row:byPen.values()){BigDecimal gain=(BigDecimal)row.get("gainKg"),kg=(BigDecimal)row.get("feedKg");row.put("feedKgPerGain",gain.signum()>0?kg.divide(gain,3,RoundingMode.HALF_UP):null);row.put("feedCostPerGain",gain.signum()>0?BigDecimal.valueOf((Long)row.get("feedCost")).divide(gain,2,RoundingMode.HALF_UP):null);rows.add(row);}
        BigDecimal feedPerGain=gainTotal.signum()>0?feedKg.divide(gainTotal,3,RoundingMode.HALF_UP):null;BigDecimal costPerGain=gainTotal.signum()>0?BigDecimal.valueOf(feedCost).divide(gainTotal,2,RoundingMode.HALF_UP):null;summary.put("averageHead",periodDays==0?null:BigDecimal.valueOf(totalHeadDays).divide(BigDecimal.valueOf(periodDays),2,RoundingMode.HALF_UP));summary.put("cattleIncluded",included);summary.put("insufficientWeights",insufficient);summary.put("averageStartWeightKg",included==0?null:startWeightTotal.divide(BigDecimal.valueOf(included),2,RoundingMode.HALF_UP));summary.put("averageEndWeightKg",included==0?null:endWeightTotal.divide(BigDecimal.valueOf(included),2,RoundingMode.HALF_UP));summary.put("totalGainKg",included==0?null:gainTotal);summary.put("averageAdgKgPerDay",average(adgValues));summary.put("feedUsedKg",included==0?null:feedKg);summary.put("feedPerKgGain",feedPerGain);summary.put("feedCostPerKgGain",costPerGain);summary.put("targetReached",targetValue==null?null:reached);summary.put("projectedDaysToTarget",average(projectedDays));if(targetValue==null)unavailable.add("The farm has no effective target finishing weight; target and projection indicators are suppressed.");
    }

    private BigDecimal weightAt(Long cattleId,LocalDate date){List<Growth> weights=em.createQuery("select g from Growth g where g.cattle.id=:id and g.status in ('VALID','CORRECTED') and g.weightKg is not null order by g.checkDate,g.id",Growth.class).setParameter("id",cattleId).getResultList();Growth before=null,after=null,nearest=null;long nearestDays=Long.MAX_VALUE;for(Growth g:weights){long diff=ChronoUnit.DAYS.between(date,g.getCheckDate());if(g.getCheckDate().isBefore(date)||g.getCheckDate().equals(date))before=g;if(g.getCheckDate().isAfter(date))after=g;if(Math.abs(diff)<nearestDays){nearest=g;nearestDays=Math.abs(diff);}}if(before!=null&&after!=null&&ChronoUnit.DAYS.between(before.getCheckDate(),date)<=60&&ChronoUnit.DAYS.between(date,after.getCheckDate())<=60){long span=ChronoUnit.DAYS.between(before.getCheckDate(),after.getCheckDate());if(span==0)return before.getWeightKg();BigDecimal fraction=BigDecimal.valueOf(ChronoUnit.DAYS.between(before.getCheckDate(),date)).divide(BigDecimal.valueOf(span),8,RoundingMode.HALF_UP);return before.getWeightKg().add(after.getWeightKg().subtract(before.getWeightKg()).multiply(fraction));}return nearest!=null&&nearestDays<=7?nearest.getWeightKg():null;}
    private LocalDate firstEntry(Long id){return em.createQuery("select min(e.entryDate) from HerdEntry e where e.cattle.id=:id and e.status=:valid",LocalDate.class).setParameter("id",id).setParameter("valid",EntryLineStatus.VALID).getSingleResult();}
    private String penAt(Long cattle,LocalDate day){return em.createQuery("select a.pen.code from PenAssignment a where a.cattle.id=:c and a.fromDate<=:day and (a.toDate is null or a.toDate>=:day) order by a.fromDate desc",String.class).setParameter("c",cattle).setParameter("day",day).setMaxResults(1).getResultStream().findFirst().orElse(null);}
    private boolean matches(Cattle c,ReportRequest r){if(r.penIds()!=null&&!r.penIds().isEmpty()){Long id=em.createQuery("select a.pen.id from PenAssignment a where a.cattle.id=:c and a.toDate is null",Long.class).setParameter("c",c.getId()).setMaxResults(1).getResultStream().findFirst().orElse(null);if(!r.penIds().contains(id))return false;}if(r.breedIds()!=null&&!r.breedIds().isEmpty()&&!r.breedIds().contains(c.getBreed().getId()))return false;if(r.lifeStages()!=null&&!r.lifeStages().isEmpty()&&!r.lifeStages().contains(c.getLifeStage().name()))return false;return r.herdGroups()==null||r.herdGroups().isEmpty()||r.herdGroups().contains(group(c));}
    private String group(Cattle c){if(c.getLifeStage()==LifeStage.UNWEANED_CALF||c.getLifeStage()==LifeStage.WEANED_CALF)return "CALVES";PurposeType p=c.getPurpose()==null?null:c.getPurpose().getPurposeType();if(p==PurposeType.FATTENING)return "FATTENING";if(p==PurposeType.SIRE)return "BREEDING_BULLS";if(p==PurposeType.BREEDING&&c.getSex()==Sex.FEMALE&&c.getLifeStage()==LifeStage.ADULT)return "BREEDING_FEMALES";if(c.getLifeStage()==LifeStage.YOUNG_STOCK)return "YOUNG_STOCK";return "OTHER";}
    private void validate(ReportRequest r){if(r==null||r.reportType()==null||r.from()==null||r.to()==null)throw DomainException.required("reportCriteria");if(r.from().isAfter(r.to()))throw DomainException.invalid("period");if(r.from().plusMonths(24).isBefore(r.to()))throw DomainException.unprocessable(MessageCodes.COM_10,"field","period","maximumMonths",24);if(!Set.of("RPT-01","RPT-02","RPT-03","RPT-04","RPT-05","RPT-06","RPT-07").contains(r.reportType()))throw DomainException.invalid("reportType");}
    private Instant start(LocalDate d,Long farm){String tz=access.require(farm,FarmAction.VIEW_REPORTS).farm().getTimeZone();return d.atStartOfDay(ZoneId.of(tz==null?"Asia/Ho_Chi_Minh":tz)).toInstant();}
    private ZoneId farmZone(Long farm){String tz=access.require(farm,FarmAction.VIEW_REPORTS).farm().getTimeZone();try{return ZoneId.of(tz);}catch(Exception ignored){return ZoneId.of("Asia/Ho_Chi_Minh");}}
    private Map<String,Object> parameters(Long farmId,LocalDate date){List<FarmParameterVersion> rows=em.createQuery("select p from FarmParameterVersion p where p.farm.id=:farm and p.effectiveFrom<=:day order by p.effectiveFrom desc,p.versionNo desc",FarmParameterVersion.class).setParameter("farm",farmId).setParameter("day",date).setMaxResults(1).getResultList();if(rows.isEmpty())return Map.of();try{return new com.fasterxml.jackson.databind.ObjectMapper().readValue(rows.get(0).getParameterValues(),new com.fasterxml.jackson.core.type.TypeReference<>(){});}catch(Exception ignored){return Map.of();}}
    private long count(String q,Long farm,LocalDate from,LocalDate to){var query=em.createQuery(q,Long.class).setParameter("farm",farm).setParameter("from",from).setParameter("to",to);if(q.contains("HerdExit")){query.setParameter("valid",ExitLineStatus.CONFIRMED).setParameter("confirmed",ExitVoucherStatus.CONFIRMED);}else query.setParameter("valid",EntryLineStatus.VALID);return query.getSingleResult();}
    private Map<String,Long> groupCount(String q,Long farm,LocalDate from,LocalDate to){var query=em.createQuery(q,Object[].class).setParameter("farm",farm).setParameter("from",from).setParameter("to",to);if(q.contains("HerdExit")){query.setParameter("valid",ExitLineStatus.CONFIRMED).setParameter("confirmed",ExitVoucherStatus.CONFIRMED);}else query.setParameter("valid",EntryLineStatus.VALID);List<Object[]> rows=query.getResultList();Map<String,Long> out=new TreeMap<>();rows.forEach(r->out.put(Objects.toString(r[0],"Unknown"),((Number)r[1]).longValue()));return out;}
    private List<Map<String,Object>> dimensions(String name,Map<String,Long> data){return data.entrySet().stream().map(e->row("dimension",name,"value",e.getKey(),"count",e.getValue())).toList();}
    private Map<String,Long> groupEnum(List<String> values){Map<String,Long> out=new TreeMap<>();values.forEach(v->out.merge(v,1L,Long::sum));return out;}
    private Map<String,Object> row(Object...pairs){Map<String,Object> out=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)out.put((String)pairs[i],pairs[i+1]);return out;}
    private BigDecimal average(List<BigDecimal> values){return values.isEmpty()?null:values.stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(values.size()),3,RoundingMode.HALF_UP);}
    private long countType(List<ReproductionEvent> rows,String type){return rows.stream().filter(e->type.equalsIgnoreCase(e.getType())).count();}
}
